contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 burnValue) public payable {
        require(burnValue <= c.balanceOf(address(this)), "burn amount must not exceed owner balance");

        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(burnValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(reverted ? supplyAfter == supplyBefore : supplyBefore == supplyAfter + burnValue);
    }

    receive() external payable {}
}

